// ORIGINALLY generated by ts-rs, and no longer regenerable: there is no
// `SchemaProposalSnapshot` type anywhere in src-tauri/ (see
// scripts/binding-orphan-allowlist.txt). `get_schema_proposal_snapshot` returns
// `serde_json::Value`, so nothing checks this file against the wire format —
// which is how `elapsed_secs` went missing from it.
//
// The real payload is `BackgroundTaskSnapshot<SchemaProposalSnapshotExtras>`
// (src-tauri/src/background_job.rs:584 + src-tauri/src/commands/credentials/
// schema_proposal.rs:31), whose `extras` are `#[serde(flatten)]`ed in:
//   job_id: String, status: String, error: Option<String>, lines: Vec<String>,
//   elapsed_secs: u64, proposed_sql: Option<String>, explanation: Option<String>
//
// Two deliberate deviations from what ts-rs would have emitted:
//  * `elapsed_secs` is OPTIONAL because the command's `None` (idle) branch
//    hand-builds its JSON object and omits the field
//    (schema_proposal.rs:138-145). Both branches are reachable from the one
//    caller, so the honest type is `?`. Fixing the Rust side to include it is
//    the better repair and belongs in a lane that can run cargo.
//  * `number`, not the `bigint` ts-rs maps `u64` to. Tauri's IPC delivers a
//    plain JS number here; the repo's convention for that is
//    `#[ts(type = "number")]` on the Rust field (314 fields already use it),
//    which this type has no source to carry.

export type SchemaProposalSnapshot = {
  job_id: string;
  status: string;
  error: string | null;
  lines: string[];
  elapsed_secs?: number;
  proposed_sql: string | null;
  explanation: string | null;
};
